function describeActivityForChat(activity) {
    switch(activity){
        case "seek_owner":
            return "找人";
        case "watch_fish":
            return "盯鱼";
        case "climb_tree":
            return "蹲在树上";
        case "look_around":
            return "东张西望";
        case "wander":
            return "慢慢溜达";
        case "play":
            return "玩闹";
        case "chase":
            return "追逐";
        case "sleep":
            return "补觉";
        case "sunbathe":
            return "晒太阳";
        case "groom":
            return "舔毛";
        default:
            return activity;
    }
}
